script:
comma.text('city', comma.data.location + ' · 未来两天天气');
comma.text('meta', '数据源：' + comma.data.source + ' · 基准时间：' + comma.data.observedAt);
comma.table('forecast', {
  columns: ['日期', '天气', '最高/最低(°C)'],
  rows: comma.data.days.map(d => [d.date, d.condition, d.high + ' / ' + d.low])
});
comma.text('note', '说明：这是评测用的固定天气数据（fixture），非实时观测。');
